    "difficulty": 2,
    "question": "正本と副本を同じ位置どうしで見比べ、副本で正本と異なっている箇所はいくつあるか。\n\n【正本】\nN　V　J　Z\nL　M　R　I\nX　Q　C　K\n\n【副本】\nA　V　T　Z\nC　M　R　I\nX　Q　B　X",
