      "ウ": "正本と副本で異なるのは、1行1列（N→A）、1行3列（J→T）、2行1列（L→C）、3行3列（C→B）、3行4列（K→X）である。合計は5か所であり、3か所ではない。",
      "エ": "正本と副本で異なるのは、1行1列（N→A）、1行3列（J→T）、2行1列（L→C）、3行3列（C→B）、3行4列（K→X）である。合計は5か所であり、2か所ではない。",
      "オ": "正本と副本で異なるのは、1行1列（N→A）、1行3列（J→T）、2行1列（L→C）、3行3列（C→B）、3行4列（K→X）である。合計は5か所であり、1か所ではない。"
